        .scoped
        .iter()
        .filter(|d| d.initiative != slug && !(retire && d.superseded_by.is_some()))
        .filter_map(|d| {
            Some(RepoRule {
                initiative: d.initiative.clone(),
                ordinal: d.ordinal,
                ts: d.ts.clone(),
                rule: d.rule.clone()?,
                quote: d.quote.clone(),
            })
